/*
  SimpleShopEducationalDb mock catalog import
  Run in SSMS after the API has started once (roles + 09120000001/002/003 exist).
  Sequence: wipe OrderItems/Orders/Products/Categories -> 10 customers -> categories -> products -> 50 orders.
  Does not delete seeded Admin/Customer users. Image files are not copied; only paths are stored.
  Copy old wwwroot/uploads into api/SimpleShop.Api/wwwroot/uploads/ yourself.
*/
USE [SimpleShopEducationalDb];
GO

SET NOCOUNT ON;
SET XACT_ABORT ON;
BEGIN TRANSACTION;

DELETE FROM [dbo].[OrderItems];
DELETE FROM [dbo].[Orders];
DELETE FROM [dbo].[Products];
DELETE FROM [dbo].[Categories];

IF NOT EXISTS (SELECT 1 FROM [dbo].[AspNetUsers] WHERE [UserName] = N'09120000002')
    THROW 50001, N'Seeded customer 09120000002 was not found. Start the API once before running this script.', 1;

IF NOT EXISTS (SELECT 1 FROM [dbo].[AspNetRoles] WHERE [NormalizedName] = N'CUSTOMER')
    THROW 50002, N'Customer role was not found. Start the API once before running this script.', 1;

DECLARE @PasswordHash NVARCHAR(MAX) = (SELECT [PasswordHash] FROM [dbo].[AspNetUsers] WHERE [UserName] = N'09120000002');
DECLARE @CustomerRoleId NVARCHAR(450) = (SELECT [Id] FROM [dbo].[AspNetRoles] WHERE [NormalizedName] = N'CUSTOMER');

