    VALUES (
        N'44444444-4444-4444-4444-444444444401', N'09121000011', N'09121000011', NULL, NULL, 0,
        @PasswordHash,
        N'44444444444444444444444444444401', N'44444444-4444-4444-4444-444444444401', N'09121000011', 1, 0, NULL, 1, 0,
        N'علی', N'محمدی', N'تهران، خیابان ولیعصر، پلاک ۱۲', N'1234567890', NULL, 1,
        CAST(N'2026-08-08T10:22:19.8306846' AS DateTime2)
