UPDATE p
SET p.[Stock] = CASE WHEN p.[Stock] - x.[Qty] < 0 THEN 0 ELSE p.[Stock] - x.[Qty] END
FROM [dbo].[Products] p
INNER JOIN (
    SELECT oi.[ProductId], SUM(oi.[Quantity]) AS [Qty]
    FROM [dbo].[OrderItems] oi
    INNER JOIN [dbo].[Orders] o ON o.[Id] = oi.[OrderId]
    WHERE o.[Status] <> N'cancelled' AND oi.[ProductId] IS NOT NULL
    GROUP BY oi.[ProductId]
) x ON x.[ProductId] = p.[Id];

SET IDENTITY_INSERT [dbo].[OrderItems] OFF;
SET IDENTITY_INSERT [dbo].[Orders] OFF;

COMMIT TRANSACTION;
GO

